def _same(got, exp: List[float]) -> bool:
    g = [float(t) for t in np.asarray(got, dtype=float).ravel()]
    if len(g) != len(exp):
        return False
    for i in range(len(g)):
        d = g[i] - exp[i]
        if d < 0.0:
            d = -d
        e = exp[i] if exp[i] >= 0.0 else -exp[i]
        if d > 1e-9 * (1.0 + e):
            return False
    return True

